CREATE DATABASE IF NOT EXISTS muto_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE muto_management;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('OWNER','ADMIN','MANAGER','ACCOUNTANT','STAFF') NOT NULL DEFAULT 'STAFF',status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',last_login DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_role(role));
CREATE TABLE IF NOT EXISTS buildings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,location VARCHAR(255) NOT NULL,description TEXT,status ENUM('ACTIVE','ARCHIVED') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS floors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,floor_number INT NOT NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,UNIQUE KEY uq_floor(building_id,floor_number));
CREATE TABLE IF NOT EXISTS units (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id BIGINT UNSIGNED NOT NULL,floor_id BIGINT UNSIGNED,unit_number VARCHAR(50) NOT NULL,unit_type ENUM('SHOP','OFFICE','ROOM') NOT NULL DEFAULT 'SHOP',name VARCHAR(120),description TEXT,monthly_rent DECIMAL(15,2) NOT NULL DEFAULT 0,status ENUM('VACANT','OCCUPIED','RESERVED','MAINTENANCE') DEFAULT 'VACANT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,FOREIGN KEY(floor_id) REFERENCES floors(id) ON DELETE SET NULL,UNIQUE KEY uq_unit(building_id,unit_number),INDEX idx_units_building(building_id),INDEX idx_units_status(status));
CREATE TABLE IF NOT EXISTS tenants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_number VARCHAR(40) NOT NULL UNIQUE,full_name VARCHAR(150) NOT NULL,business_name VARCHAR(180),phone VARCHAR(30) NOT NULL,email VARCHAR(180),address VARCHAR(255),national_id_optional VARCHAR(80),emergency_contact VARCHAR(150),status ENUM('ACTIVE','ARCHIVED') DEFAULT 'ACTIVE',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_tenant_phone(phone),INDEX idx_tenant_status(status));
CREATE TABLE IF NOT EXISTS leases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,monthly_rent DECIMAL(15,2) NOT NULL,security_deposit DECIMAL(15,2) DEFAULT 0,payment_due_day TINYINT UNSIGNED DEFAULT 5,status ENUM('ACTIVE','EXPIRED','TERMINATED','UPCOMING') DEFAULT 'UPCOMING',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(unit_id) REFERENCES units(id),INDEX idx_lease_dates(start_date,end_date),INDEX idx_lease_status(status));
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receipt_number VARCHAR(50) NOT NULL UNIQUE,tenant_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,lease_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(15,2) NOT NULL,payment_date DATE NOT NULL,payment_method ENUM('CASH','MOBILE_MONEY','BANK','OTHER') NOT NULL,transaction_reference VARCHAR(120),period_from DATE,period_to DATE,notes TEXT,recorded_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(unit_id) REFERENCES units(id),FOREIGN KEY(lease_id) REFERENCES leases(id),FOREIGN KEY(recorded_by) REFERENCES users(id),UNIQUE KEY uq_transaction(transaction_reference),INDEX idx_payment_date(payment_date),INDEX idx_payment_tenant(tenant_id));
CREATE TABLE IF NOT EXISTS rent_charges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,lease_id BIGINT UNSIGNED NOT NULL,period_from DATE NOT NULL,period_to DATE NOT NULL,amount DECIMAL(15,2) NOT NULL,amount_paid DECIMAL(15,2) DEFAULT 0,status ENUM('UNPAID','PARTIALLY_PAID','PAID','OVERDUE') DEFAULT 'UNPAID',due_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(unit_id) REFERENCES units(id),FOREIGN KEY(lease_id) REFERENCES leases(id),INDEX idx_charge_status(status),INDEX idx_charge_tenant(tenant_id));
CREATE TABLE IF NOT EXISTS maintenance_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_number VARCHAR(40) NOT NULL UNIQUE,building_id BIGINT UNSIGNED NOT NULL,unit_id BIGINT UNSIGNED,tenant_id BIGINT UNSIGNED,title VARCHAR(180) NOT NULL,description TEXT,priority ENUM('LOW','MEDIUM','HIGH','URGENT') DEFAULT 'MEDIUM',status ENUM('OPEN','IN_PROGRESS','ON_HOLD','COMPLETED','CANCELLED') DEFAULT 'OPEN',assigned_to BIGINT UNSIGNED,estimated_cost DECIMAL(15,2) DEFAULT 0,actual_cost DECIMAL(15,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,resolved_at DATETIME,FOREIGN KEY(building_id) REFERENCES buildings(id),FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE SET NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE SET NULL,FOREIGN KEY(assigned_to) REFERENCES users(id),INDEX idx_maintenance_status(status));
CREATE TABLE IF NOT EXISTS documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_type VARCHAR(40) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,file_name VARCHAR(255) NOT NULL,file_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recipient VARCHAR(180) NOT NULL,type VARCHAR(30) NOT NULL,subject VARCHAR(180),message TEXT NOT NULL,status ENUM('PENDING','SENT','FAILED') DEFAULT 'PENDING',sent_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50),entity_id BIGINT UNSIGNED,description TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_audit_date(created_at),INDEX idx_audit_user(user_id));
